using DbToEntity.Tests.Infrastructure;
using Microsoft.CodeAnalysis;
using Microsoft.EntityFrameworkCore;

namespace DbToEntity.Tests;

/// <summary>User code that lives next to the generated files and must survive regeneration (F5).</summary>
public class CustomizationTests
{
    private static SchemaBuilder Users()
    {
        var s = new SchemaBuilder();
        s.Table("users", "User", "*id", "email:varchar(255)", "first_name:text", "last_name:text");
        return s;
    }

    [Fact]
    public void OnModelCreatingPartial_RunsAfterGeneratedConfiguration()
    {
        // The user's own file: overrides a generated setting and adds a new one.
        var custom = """
            using Microsoft.EntityFrameworkCore;
            namespace Generated
            {
                public partial class AppDbContext
                {
                    partial void OnModelCreatingPartial(ModelBuilder modelBuilder)
                    {
                        modelBuilder.Entity<User>(entity =>
                        {
                            entity.Property(e => e.Email).HasMaxLength(100);         // generated: 255
                            entity.HasIndex(e => e.Email).HasDatabaseName("ix_custom_email");
                        });
                    }
                }
            }
            """;

        var model = GeneratedModel.Build(Users(), new() { ["AppDbContext.Custom.cs"] = custom });
        var user = model.Entity("User");

        Assert.Equal(100, user.FindProperty("Email")!.GetMaxLength());
        Assert.Contains(user.GetIndexes(), i => i.GetDatabaseName() == "ix_custom_email");
    }

    [Fact]
    public void PartialEntity_CanAddUnmappedMembers()
    {
        var custom = """
            using System.ComponentModel.DataAnnotations.Schema;
            namespace Generated
            {
                public partial class User
                {
                    [NotMapped]
                    public string FullName => FirstName + " " + LastName;
                }
            }
            """;

        var user = GeneratedModel.Build(Users(), new() { ["User.Custom.cs"] = custom }).Entity("User");

        Assert.NotNull(user.ClrType.GetProperty("FullName"));
        Assert.Null(user.FindProperty("FullName"));
    }

    [Fact]
    public void WithoutUserFile_PartialHookIsOptional()
    {
        var model = GeneratedModel.Build(Users());

        Assert.Contains("partial void OnModelCreatingPartial(ModelBuilder modelBuilder);", model.Sources["AppDbContext.cs"]);
        Assert.Contains("public partial class AppDbContext : DbContext", model.Sources["AppDbContext.cs"]);
    }

    [Fact]
    public void EveryGeneratedFile_StartsWithAutoGeneratedHeader()
    {
        var s = Users();
        s.Enum("public", "mood", "happy");

        var model = GeneratedModel.Build(s);

        Assert.All(model.Sources, file => Assert.StartsWith("// <auto-generated>", file.Value));
    }

    // Projects with <Nullable>enable</Nullable> must not get warnings from generated files: the
    // <auto-generated> header makes the compiler treat them as generated code.
    [Fact]
    public void GeneratedCode_ProducesNoNullableWarnings_InNullableEnabledProject()
    {
        var s = new SchemaBuilder();
        var role = s.Table("roles", "Role", "*id", "name:text");
        var user = s.Table("users", "User", "*id", "email:text", "nickname:text?", "role_id?");
        s.ForeignKey("fk_user_role", user, "role_id", role);

        var diagnostics = GeneratedModel.Build(s).Diagnostics(NullableContextOptions.Enable);

        Assert.Empty(diagnostics.Where(d => d.Severity >= DiagnosticSeverity.Warning).Select(d => d.ToString()));
    }
}
